      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Acute neurological symptom review"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No acute change in speech or vision and no limb weakness reported."
      }
    },
